import { test, expect } from '@playwright/test';

test.describe('Billing Address Change during Checkout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/checkout');
    await page.fill('input[name="email"]', 'user@example.com');
    await page.fill('input[name="password"]', 'password123');
    await page.click('button[type="submit"]');
  });

  test('should allow user to change billing address', async ({ page }) => {
    await page.click(getByText('Change Billing Address'));
    await page.fill(getByLabel('Street Address'), '123 New St');
    await page.fill(getByLabel('City'), 'New City');
    await page.fill(getByLabel('State'), 'New State');
    await page.fill(getByLabel('Zip Code'), '12345');
    await page.click(getByText('Save Address'));

    const successMessage = await page.locator(getByText('Billing address updated successfully'));
    await expect(successMessage).toBeVisible();
  });

  test('should display error for invalid billing address', async ({ page }) => {
    await page.click(getByText('Change Billing Address'));
    await page.fill(getByLabel('Street Address'), '');
    await page.fill(getByLabel('City'), 'New City');
    await page.fill(getByLabel('State'), 'New State');
    await page.fill(getByLabel('Zip Code'), '12345');
    await page.click(getByText('Save Address'));

    const errorMessage = await page.locator(getByText('Street Address is required'));
    await expect(errorMessage).toBeVisible();
  });
});
